-- 샤갈 (d8kf6t9w / 샤갈)
update public.memes set
  description = '어이없거나 황당하고 당황스러운 상황에서 반응처럼 내뱉는 인터넷 유행어이다. ''어이없다'', ''현타 온다'' 같은 말을 대신하는 감탄사로 쓰이며, 사전적으로 정해진 뜻은 없고 문맥에 따라 느낌이 달라진다. 유튜브 채널 ''여단오''에서 나온 말버릇이 시청자 사이에서 밈처럼 퍼진 뒤 쇼츠, 릴스, 댓글을 타고 확산된 것으로 보도되었다. 비슷한 시기에 기분이 좋을 때 쓰는 ''야르''와 함께 최근 신조어로 자주 묶여 소개된다. 정해진 사전적 의미가 없어 상황에 따라 황당함, 짜증, 허탈함 등 여러 감정을 두루 담는 것이 특징이며, 젠지어 소개 기사에서도 자주 언급된다.',
  origin = '경기일보 보도에 따르면 유튜브 채널 ''여단오''에서 진행자가 쓰던 말버릇이 밈이 되어 쇼츠·릴스·댓글로 퍼졌다. 구체적인 최초 방송일, 말버릇의 정확한 형태, 유래의 세부 사정은 열어본 자료에서 확인하지 못했다.',
  usage_note = '예상 밖의 일이 생겼을 때나 어이없는 상황을 짧게 표현할 때 댓글, 단체 채팅방, 숏폼 자막에서 감탄사처럼 쓴다. 뜻이 고정되어 있지 않아 친한 사이의 가벼운 대화에서 주로 쓰이고, 상대가 모르면 설명이 필요하다.',
  caution = '정해진 정의가 없는 최신 유행어라 세대나 커뮤니티에 따라 이해 정도가 다르고 유행이 짧게 끝날 수 있다. 격식 있는 자리나 윗사람에게 쓰면 무례하거나 뜻이 전달되지 않을 수 있으며, 특정인을 조롱하는 말투로 쓰는 것은 피하는 것이 좋다.',
  usage_examples = '[{"situation":"갑자기 약속이 취소되었을 때","text":"아니 오늘 약속 당일에 취소됨... 샤갈이다 진짜"},{"situation":"예상 못 한 결과에 당황했을 때","text":"과제 파일 저장 안 하고 꺼버렸네 ㅋㅋ 샤갈"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'd8kf6t9w'
  and slug = '샤갈'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

