-- 야르 (sejp2dtf / 야르)
update public.memes set
  description = '''신난다'', ''야호'', ''앗싸''처럼 기분이 좋거나 들뜰 때 내뱉는 감탄사이다. 최근에는 ''야르하다'', ''야르함''처럼 뒤에 ''-하다''를 붙여 분위기나 장소가 좋다는 뜻의 서술어로도 쓰인다. 예를 들어 월급날을 맞아 ''야르~''라고 외치거나 카페 조명이 좋다고 말할 때 쓴다. 새로운 말처럼 보이지만 2000년대 초중반부터 쓰인 기록이 있으며, 최근 10~20대 사이에서 다시 유행하며 주목받았다. 일상 대화에서는 월급날이나 약속이 즐거울 때 가볍게 외치는 식으로 쓰이고, 뜻이 비교적 단순해 세대를 넘어 이해하기 쉬운 편이다. 유래에는 여러 설이 있다.',
  origin = '위키트리와 인사이트에 따르면 배우 봉태규가 2003년 영화 <바람난 가족>에서 애드리브로 처음 썼다고 주장했고, 2006년 네이버 오픈사전에 ''좋다''는 뜻으로 등재되었으며 2008년 <무한도전>에서 정형돈이 외쳤다. 2009년 <꽃보다 남자> 촬영 영상에도 등장한다. 최초 사용자는 확정되지 않았다.',
  usage_note = '기분 좋은 일이 생겼을 때 감탄사로 쓰거나 ''야르하다''로 어떤 대상이 마음에 든다는 의미를 표현할 때 쓴다. 주로 10~20대의 채팅, 댓글, 숏폼에서 가볍고 장난스럽게 사용한다.',
  caution = '뜻이 고정되지 않은 유행어라 연령대에 따라 이해하지 못할 수 있고, 유행이 지나면 어색해질 수 있다. 봉태규 최초 사용설은 본인 주장에 근거한 것이어서 사실처럼 단정하면 안 되며, 격식을 갖춘 글이나 공식 문서에는 어울리지 않는다.',
  usage_examples = '[{"situation":"월급날 친구에게","text":"오늘 월급날이다 야르~ 오늘은 내가 쏜다"},{"situation":"새로 간 카페가 마음에 들 때","text":"여기 분위기 진짜 야르하다 자주 와야겠어"}]'::jsonb,
  origin_year = null,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'sejp2dtf'
  and slug = '야르'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

