-- 아이스버킷챌린지 (wgvn5snt / 아이스버킷챌린지)
update public.memes set
  description = '얼음물을 양동이째 뒤집어쓴 뒤 다음 참가자를 지목하고, 지목받은 사람은 일정 시간 안에 같은 행동을 하거나 기부하도록 하는 릴레이 캠페인이다. 루게릭병(ALS) 환자를 돕고 연구 기금을 모으자는 취지로 2014년 여름 세계적으로 확산되었다. 빌 게이츠 등 유명인이 참여했고 한국에서도 연예인, 체육인, 정치인이 줄지어 동참했다. 기부 없이 이벤트만 남는다는 비판도 함께 제기된 사례이다. 한국에서는 이 열풍을 계기로 루게릭병 요양병원을 짓는 승일희망재단에 기부 문의가 늘었다는 보도가 있었다.',
  origin = '경향신문은 2014년 6월 미국 루게릭병협회가 제안한 캠페인이 세계로 번졌다고 보도했다. 한국에서는 머니투데이 기준 2014년 8월 17일 가수 팀이 첫 참여자로 알려졌고 유재석, 박명수, 손흥민 등이 뒤를 이었다. 얼음물 기부의 정확한 시초는 불분명하다고 한다.',
  usage_note = '챌린지 릴레이로 기부 문화를 확산시킨 대표 사례를 이야기할 때, 또는 지목을 받아 무언가를 해야 하는 상황을 농담처럼 말할 때 인용한다. 이후 유사한 지목형 챌린지를 설명할 때 비교 대상으로도 쓰인다.',
  caution = '루게릭병 환자와 가족이 겪는 고통이 배경이므로 가볍게 희화화하거나 환자를 조롱하는 방식으로 쓰면 안 된다. 얼음물만 뒤집어쓰고 기부는 빠지는 ''슬랙티비즘'' 비판이 있었음을 기억해야 하며, 특정 정치인이나 연예인의 참여 여부를 단정하기 전에 확인이 필요하다.',
  usage_examples = '[{"situation":"지목형 챌린지가 유행할 때","text":"이거 완전 아이스버킷챌린지처럼 다음 사람 지목하는 방식이네"},{"situation":"기부 챌린지 이야기를 할 때","text":"요즘 기부 챌린지 보니까 2014년 아이스버킷챌린지 때가 생각난다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'wgvn5snt'
  and slug = '아이스버킷챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

