-- 박지성 첼시전 결승골 (bb2yhqtv / 박지성-첼시전-결승골)
update public.memes set
  description = '2010-11 UEFA 챔피언스리그 8강 2차전에서 맨체스터 유나이티드의 박지성이 첼시를 상대로 터뜨린 결승골을 가리킨다. 첼시의 드로그바가 동점골을 넣은 직후 박지성이 왼발 슛으로 곧바로 2-1 리드를 되찾았고, 팀은 합계 3-1로 4강에 올랐다. 큰 경기에서 결정적인 순간에 해결사 역할을 했다는 평가와 함께 한국 축구 팬들이 박지성의 대표 장면으로 즐겨 언급한다. 당시 언론은 이 골이 박지성의 시즌 7호이자 챔피언스리그 4호 골이었다고 전했다.',
  origin = '2011년 4월 13일(한국시간) 올드 트래퍼드에서 열린 맨유 대 첼시 8강 2차전이다. 1차전은 맨유가 1-0으로 이겼다. 드로그바 동점골 직후 박지성이 득점했다는 점은 두 보도가 일치하나, 정확한 득점 분은 보도마다 달라 확인하지 못했다.',
  usage_note = '박지성의 전성기나 큰 경기에 강했던 모습을 이야기할 때, 또는 짧은 시간에 분위기를 뒤집는 순간을 비유할 때 쓴다. 축구 커뮤니티에서 ''박지성 첼시전 골 기억나냐'' 같은 식으로 추억을 꺼낼 때 자주 나온다.',
  caution = '2011년의 경기 장면이라 최신 유행 밈이 아니며, 영상 클립은 방송사나 구단의 저작권이 있어 무단 재편집·재업로드에 주의해야 한다. 또한 득점 분이나 도움 선수 등 세부 사항은 기억에 의존해 단정하지 않는 편이 안전하다.',
  usage_examples = '[{"situation":"축구 커뮤니티에서 추억을 이야기할 때","text":"박지성 첼시전 골 아직도 소름 돋는다, 드로그바 동점골 직후에 바로 넣었잖아ㅋㅋ"},{"situation":"친구와 월드컵 얘기를 하다가","text":"큰 경기에서 한 방 해주는 건 박지성이지, 첼시전 결승골 기억나지?"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'bb2yhqtv'
  and slug = '박지성-첼시전-결승골'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

