-- 저숭라라 (fbmmjgmr / 저숭라라)
update public.memes set
  description = '''저승나라''를 귀엽게 비튼 인터넷 표현으로, 몹시 힘들거나 아찔한 상황을 과장해서 말할 때 쓴다. ''하늘나라''를 줄인 긍정 표현 ''하룰라라''의 반대편에 놓이는 말로 소개된다. 육아 분야에서는 아이 때문에 지친 하루를 부모끼리 서로 위로하며 농담처럼 말하는 데도 쓰인다. 심각한 상황을 무겁지 않게 웃음으로 넘기려는 가벼운 말투가 특징이다. 다만 어디서 처음 쓰였는지는 분명하지 않아 정확한 기원보다는 쓰임새 중심으로 이해하는 편이 좋다. 비슷한 ''~라라'' 말놀이가 여럿 있다.',
  origin = '''하룰라라''가 X(옛 트위터)에서 콘서트 좌석 관련 트윗을 계기로 밈이 된 뒤, 그 반대 의미로 만들어진 파생어로 설명된다. 저숭라라 자체가 처음 등장한 시점과 만든 사람은 출처에서 확인하지 못했다.',
  usage_note = '야근, 시험, 육아 등으로 지치거나 일이 꼬였을 때 ''오늘 완전 저숭라라''처럼 과장해 쓴다. 좋은 일에 쓰는 ''하룰라라''와 짝으로 사용하면 대비 효과가 커진다.',
  caution = '가벼운 농담용 표현이라 실제로 고인이나 죽음과 관련된 상황, 심각한 고통을 겪는 사람 앞에서 쓰면 불쾌감을 줄 수 있다. 유행어 수명이 짧을 수 있고 연령대에 따라 모르는 사람도 많으니 상대를 가려 사용해야 한다.',
  usage_examples = '[{"situation":"야근이 겹친 날 친구에게","text":"오늘 보고서 세 개 겹쳤어ㅋㅋ 완전 저숭라라다"},{"situation":"육아 커뮤니티 댓글","text":"오늘 아이 열 나고 난리였어요... 저숭라라 다녀왔습니다ㅠㅠ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'fbmmjgmr'
  and slug = '저숭라라'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

