-- 파리의 연인 - 애기야, 가자 (hfm8tfmd / 파리의-연인---애기야,-가자)
update public.memes set
  description = '2004년 SBS 주말드라마 ''파리의 연인''에서 박신양이 연기한 한기주가 곤경에 처한 태영을 구해 주려고 연인인 척 데려가며 건넨 대사 ''애기야, 가자''를 가리킨다. 극 중 박력과 다정함이 섞인 장면 덕분에 방영 당시 큰 인기를 끌었고, 친구끼리 서로를 ''애기야''라고 부르는 유행까지 낳았다. 이후 드라마 명대사를 이야기할 때 대표 사례로 자주 소환되며, 같은 드라마의 ''이 안에 너 있다''와 함께 김은숙 작가 대사의 출발점으로 거론된다. 방영 당시 패러디와 개그 소재로도 널리 쓰였다.',
  origin = '2004년 SBS 주말드라마 ''파리의 연인''에서 박신양(한기주 역)이 김정은(강태영 역)에게 한 대사다. 서울신문은 방송 20회에서 나온 대사로 전했고, 그해 인터넷 투표 등에서 최고 유행어로 꼽혔다고 보도했다. 작가는 김은숙이다.',
  usage_note = '연인이나 친구를 장난스럽게 재촉하거나 챙겨서 데려갈 때, 또는 드라마 대사를 패러디하는 분위기에서 쓴다. 중장년층에게는 향수를 부르는 대사여서 2000년대 드라마 이야기를 할 때 자주 나온다.',
  caution = '20년 전 드라마 대사라 젊은 층은 원본 맥락을 모를 수 있고, 상대를 ''애기''라고 부르는 표현이 어린아이 취급처럼 들려 불쾌할 수 있다. 드라마 장면 클립은 방송사의 저작권이 있으니 무단 편집 영상 사용에 주의해야 한다.',
  usage_examples = '[{"situation":"친구를 장난스럽게 재촉할 때","text":"빨리 나와~ 애기야, 가자ㅋㅋ 늦겠다"},{"situation":"옛 드라마 이야기 댓글","text":"파리의 연인 애기야 가자 이 대사 아직도 기억나는 사람ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'hfm8tfmd'
  and slug = '파리의-연인---애기야,-가자'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

