-- 꽁냥이 챌린지 (2vpmxvjs / 꽁냥이-챌린지)
update public.memes set
  description = 'MBN 뉴스 리포트 속 ''꽁꽁 얼어붙은 한강 위로 고양이가 걸어다닙니다''라는 기자의 멘트에 음악과 손동작 안무를 붙여 추는 SNS 챌린지다. 원본 영상은 2021년 말 한파 보도였으나 2024년 4월 무렵 틱톡 등에서 다시 크게 확산됐고, 아이돌과 인플루언서가 대거 따라 췄다. 리듬이 중독적이고 동작이 쉬워 널리 퍼졌다고 보도됐다. 이후 원본 속 고양이가 실제 길고양이였고 영상을 찍은 기자가 입양했다는 후일담도 화제가 되었다. 사람들은 이를 귀여운 인터넷 문화의 사례로 즐겼다.',
  origin = '2021년 12월 27일 MBN 뉴스7에서 이시열 기자가 뚝섬한강공원의 얼어붙은 한강 위를 걷는 고양이를 소개하며 한 멘트가 출발점이다. 처음에는 곧 잊혔다가 2024년 4월 재조명됐다. 안무를 처음 만든 사람은 출처에서 확인하지 못했다.',
  usage_note = '추운 날씨나 귀여운 고양이 영상, 가벼운 춤 챌린지를 소개할 때 인용한다. 멘트 자체를 ''꽁꽁 얼어붙은 한강 위로~'' 하고 따라 말하며 댓글 놀이로 쓰기도 한다.',
  caution = '원본은 실제 방송사 뉴스 영상이라 클립 재사용 시 저작권 문제가 있을 수 있고, 특정 기자의 얼굴과 목소리가 드러나므로 조롱 목적으로 쓰는 것은 피해야 한다. 2024년 유행한 밈이라 지금은 시기가 지난 표현으로 받아들여질 수 있다.',
  usage_examples = '[{"situation":"한파가 온 날 단체 채팅방","text":"오늘 날씨 실화냐ㅋㅋ 꽁꽁 얼어붙은 한강 위로 고양이가 걸어다닙니다"},{"situation":"고양이 영상 댓글","text":"이 고양이 걸음걸이 보니까 꽁냥이 챌린지 춤 춰야 할 듯ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '2vpmxvjs'
  and slug = '꽁냥이-챌린지'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

