-- 오징어게임 깐부 (a97cbw2z / 오징어게임-깐부)
update public.memes set
  description = '깐부는 딱지치기나 구슬치기에서 한 편이 되어 물건을 함께 쓰는 가장 친한 놀이 친구를 가리키는 속어다. 국립국어원 표준국어대사전에는 오르지 않은 말이었으나, 2021년 넷플릭스 드라마 ''오징어 게임''에서 오일남이 성기훈에게 "우리는 깐부잖아"라고 말하는 장면이 알려지면서 널리 퍼졌다. 이후 친한 사이나 같은 편임을 강조하는 표현으로 쓰이며, 넷플릭스와 트위터 공식 계정이 서로 ''깐부''를 주고받은 일도 화제가 됐다. 어린 시절의 놀이 문화에서 나온 단어가 드라마를 통해 다시 주목받은 사례로 볼 수 있다.',
  origin = '2021년 넷플릭스 ''오징어 게임''에서 오일남이 성기훈에게 건넨 "우리는 깐부잖아" 대사로 알려졌다. 단어 자체는 동네 놀이 문화에서 쓰이던 말이며, 정확한 어원은 열람한 출처에서 확인되지 않았다.',
  usage_note = '친한 사이임을 강조하거나 같은 편으로 묶일 때 "우리 깐부잖아"처럼 가볍게 쓴다. 부탁을 하거나 의리를 확인하는 장난스러운 상황, 함께 무언가를 도모하는 친구 사이의 댓글과 메시지에 어울린다.',
  caution = '드라마의 맥락은 목숨을 건 생존 게임이므로 심각한 상황에 가볍게 쓰면 부적절해 보일 수 있다. 이익을 위해 뭉친 관계를 비꼬는 용법으로도 쓰이니 상대에 따라 오해가 없도록 하고, 배우의 모습을 조롱하는 합성물은 피하는 것이 좋다.',
  usage_examples = '[{"situation":"친구에게 부탁할 때","text":"이번 조별과제 같이 하자, 우리 깐부잖아~"},{"situation":"댓글","text":"둘이 진짜 깐부 인정ㅋㅋ 이 조합 계속 보고 싶다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'a97cbw2z'
  and slug = '오징어게임-깐부'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

