-- 김건모 '잘못된 만남' (jbfcvawr / 김건모-잘못된-만남)
update public.memes set
  description = '1995년 1월 발매된 김건모의 3집 앨범과 그 타이틀곡 ''잘못된 만남''을 가리킨다. 사랑하던 사람이 친구에게로 떠나 버린 삼각관계를 담담하게 풀어낸 노랫말과 귀에 감기는 멜로디로 큰 인기를 얻었고, 음악 방송 순위에서 단기간에 정상에 올랐다. 앨범은 발매 두 달여 만에 200만 장을 넘겼고 이후 오랫동안 국내 최다 판매 기록으로 남아 1990년대 가요 전성기를 상징하는 곡으로 거론된다. 지금도 90년대 노래를 회상하거나 삼각관계 상황을 농담 삼아 말할 때 자주 인용된다.',
  origin = '1995년 1월 21일 라인프로덕션에서 발매된 김건모 3집의 타이틀곡이다. 1995년 3월 서울신문 보도 기준으로 앨범은 약 230만 장이 팔렸고, 3월 10일에 200만 장을 돌파한 것으로 정리된다.',
  usage_note = '90년대 가요를 추억하는 대화나 댓글에서 ''그 시절 최고 히트곡''의 예로 언급한다. 또 친구와 연인 사이의 삼각관계, 의도치 않게 얽힌 인간관계를 장난스럽게 표현할 때 제목 그대로 ''이거 완전 잘못된 만남이네''처럼 인용한다.',
  caution = '노래의 상황은 연인과 친구 사이의 배신을 다루므로 실제 지인의 연애사를 농담거리로 삼으면 상대에게 상처가 될 수 있다. 또한 오래된 곡이라 젊은 세대에게는 맥락이 전달되지 않을 수 있으며, 음원이나 방송 클립을 그대로 재게시할 때는 저작권에 유의해야 한다.',
  usage_examples = '[{"situation":"친구와 전 애인이 사귀게 된 이야기를 들었을 때","text":"와 이건 진짜 김건모 잘못된 만남 급이다 ㅋㅋ"},{"situation":"90년대 노래 이야기가 나온 단톡방","text":"그때 길거리마다 잘못된 만남만 나왔던 거 기억나? 레전드였지"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'jbfcvawr'
  and slug = '김건모-잘못된-만남'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

