-- 베이지 플래그(Beige Flag) (pg8ds9j3 / 베이지-플래그(Beige-Flag))
update public.memes set
  description = '연애 상대의 행동이 좋지도 나쁘지도 않으면서 괜히 눈길을 끄는 사소하고 특이한 성향을 가리키는 표현이다. 상대로서의 매력을 높이는 초록 깃발, 경계해야 할 빨간 깃발 사이에 놓인 중립적인 색으로 베이지를 고른 말이다. 알람 대신 타이머를 맞추는 습관처럼 별것 아니지만 한 번쯤 멈칫하게 되는 버릇을 두고 소셜미디어에서 가볍게 공유하며 퍼졌다. 영어권 틱톡에서 시작된 용어가 국내에도 소개되어 쓰이고 있다. 용어 자체는 자동차 경주의 깃발에서 따온 빨간·초록 깃발 표현의 연장선에 있다.',
  origin = '영어 ''beige flag''는 2022년 무렵 틱톡 등에서 쓰이기 시작했고, 2023년 들어 ''엉뚱하고 독특한 행동''이라는 뜻으로 널리 퍼졌다. 처음 만든 사람은 출처에서 확인되지 않는다. 한국에서의 확산 경로는 확인하지 못했다.',
  usage_note = '연인이나 친구의 사소한 버릇을 흉보지 않고 귀엽게 소개할 때 ''이건 베이지 플래그야''라고 쓴다. 자신의 특이한 습관을 먼저 고백하는 글이나 영상에도 해시태그 형태로 붙이는 경우가 많다.',
  caution = '가벼운 놀이용 표현이지만 상대의 행동을 깃발 색으로 평가하는 방식이어서 실제 지인을 공개 게시물에서 판정하면 불쾌감을 줄 수 있다. 또 베이지와 빨간 깃발의 경계는 사람마다 달라, 위험 신호가 될 행동을 ''베이지''라고 넘기지 않도록 주의해야 한다.',
  usage_examples = '[{"situation":"남자친구의 습관을 이야기하며","text":"알람 안 맞추고 타이머만 쓰는 거 완전 베이지 플래그 아님?ㅋㅋ"},{"situation":"친구의 독특한 취향을 들었을 때","text":"라면에 케첩 넣는다고? 그건 레드까진 아니고 베이지 플래그다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'pg8ds9j3'
  and slug = '베이지-플래그(Beige-Flag)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

