-- 야신 (김성근) (hhzctgjd / 야신-(김성근))
update public.memes set
  description = '야신은 ''야구의 신''을 줄인 말로 김성근 감독을 가리키는 별명이다. 2002년 한국시리즈에서 삼성을 우승시킨 김응용 감독이 상대 팀 사령탑이던 김성근 감독을 두고 ''야구의 신과 경기하는 것 같았다''고 말한 것이 계기로 소개된다. 이후 언론은 이 시리즈 이후 김성근 감독이 야신으로 불렸다고 적었고, 치밀한 작전과 승부 집념을 지닌 감독을 높여 부르는 말로 자리 잡았다. 야구 팬들은 작전이 맞아떨어진 경기에서 감독을 칭찬하거나 가볍게 풍자할 때 이 표현을 쓴다.',
  origin = '2002년 한국시리즈에서 삼성 김응용 감독이 LG 김성근 감독을 ''야구의 신''에 빗댄 발언이 출발점으로 소개된다. 2014년 기사도 2002년 한국시리즈 이후 야신으로 불렸다고 적는다. 정확한 발언의 현장 상황과 문구는 추가로 확인하지 못했다.',
  usage_note = '야구 중계나 커뮤니티에서 감독이 대타, 투수 교체, 작전 등을 적중시켰을 때 ''역시 야신''처럼 감탄하며 쓴다. 감독의 지나친 간섭이나 혹사 논란을 비꼬는 맥락에서 반어적으로 쓰이기도 한다.',
  caution = '실존 인물의 별명이므로 평가가 갈리는 훈련 방식이나 선수 기용 논란을 조롱하는 용도로 쓰면 불쾌감을 줄 수 있다. 존칭 성격이 강한 별명이라 다른 감독에게 무분별하게 붙이면 어색하게 들린다.',
  usage_examples = '[{"situation":"야구 경기 중계 채팅","text":"저 타이밍에 대타라니 ㅋㅋ 이 감독 오늘 야신 빙의했네"},{"situation":"커뮤니티 댓글","text":"작전 야구는 역시 야신이 원조지, 요즘 감독들이 보고 배워야 함"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'hhzctgjd'
  and slug = '야신-(김성근)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

