-- 지메시 (지소연) (j2cq5dpe / 지메시-(지소연))
update public.memes set
  description = '지메시는 지소연의 성과 축구 선수 메시의 이름을 합친 별명이다. 지소연은 2010년 U-20 여자월드컵에서 한국의 사상 첫 세계 3위에 기여하며 대회 8골로 은공과 은화를 받았고, 이 활약을 계기로 팬과 언론이 그를 지메시로 불렀다. 본인은 2018년 방송에서 이 별명을 8년 전 독일 월드컵에서 얻었다고 설명하면서, 당시 섀도 스트라이커였지만 지금은 미드필더라 어울리지 않는다고 말했다. 한국 여자축구 간판 선수의 개인기를 칭찬할 때 쓰는 표현이다.',
  origin = '별명은 2010년 독일에서 열린 U-20 여자월드컵 활약 무렵에 붙은 것으로 확인된다. 2010년 8월 스포츠경향 기사에 이미 ''지메시''로 표기되어 있고, 지소연 본인도 2018년 방송에서 8년 전 독일 월드컵에서 얻은 별명이라고 밝혔다.',
  usage_note = '여자축구 경기나 하이라이트 영상에서 드리블과 득점으로 분위기를 바꾸는 장면에 ''지메시 나왔다''처럼 감탄하는 용도로 쓴다. 국가대표 경기 응원 댓글에서도 자주 보인다.',
  caution = '본인이 현재 포지션과 어울리지 않아 별명을 썩 좋아하지 않는다고 밝힌 바 있어, 본인 앞이나 공식 자리에서 강요하듯 쓰는 것은 피하는 편이 좋다. 외모나 성별을 들어 남자 선수와 비교하는 식의 비하 발언과 엮이지 않도록 주의해야 한다.',
  usage_examples = '[{"situation":"여자축구 대표팀 경기 중계 댓글","text":"방금 탈압박 봤냐 ㅋㅋ 역시 지메시다"},{"situation":"친구와 카톡","text":"어제 지소연 프리킥 영상 봄? 지메시 별명 괜히 나온 게 아니더라"}]'::jsonb,
  origin_year = 2010,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'j2cq5dpe'
  and slug = '지메시-(지소연)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

