-- 코티지코어 (k9ftbbv2 / 코티지코어)
update public.memes set
  description = '코티지코어는 작은 시골집(cottage)에서의 소박한 생활을 동경하는 감성을 뜻하는 말로, 패션과 라이프스타일 양쪽에서 쓰인다. 레이스, 프릴, 크로셰, 꽃무늬, 니트 같은 유럽 전원 분위기의 요소가 대표적이며, 정원 가꾸기나 빵 굽기, 재봉틀로 옷 만들기 같은 취미와 함께 소비된다. 코로나19로 집에 머무는 시간이 늘어난 2020년에 크게 유행했고, 엔데믹 이후 한동안 잠잠했다가 셀럽 착장을 통해 다시 주목받았다. 한국 패션 매체에서도 하나의 스타일 키워드로 다룬다.',
  origin = '2020년 코로나19 확산기에 유행한 것으로 보그 코리아와 허프포스트가 설명한다. 허프포스트는 틱톡과 인스타그램에서 퍼졌고 3월부터 관련 검색이 늘었다고 전한다. 특정 한 사람이나 한 영상이 시초인지는 확인되지 않았다.',
  usage_note = '전원풍 원피스, 레이스 블라우스, 바구니 가방 같은 코디를 설명하거나 시골 감성의 취미 콘텐츠를 소개할 때 쓴다. ''이번 주말은 코티지코어 감성으로 빵 굽기''처럼 일상 분위기를 표현하는 말로도 쓰인다.',
  caution = '유행 주기가 빨라 시기가 지난 표현으로 들릴 수 있고, 매체마다 범위를 달리 설명하므로 정확한 정의를 단정하기 어렵다. 허프포스트는 유럽 귀족의 전원놀이 같은 역사적 배경과 자본주의에 대한 피로감도 거론하는 만큼, 시골 생활을 지나치게 낭만화한다는 비판이 있을 수 있다.',
  usage_examples = '[{"situation":"패션 SNS 게시글","text":"프릴 블라우스에 바구니백 매치했더니 완전 코티지코어 감성이다"},{"situation":"친구와 카톡","text":"주말에 집에서 빵 굽고 화분 가꾸는 중~ 나 요즘 코티지코어에 빠졌나 봐"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'k9ftbbv2'
  and slug = '코티지코어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

