-- 청춘불패 (kypyp4vj / 청춘불패)
update public.memes set
  description = '청춘불패는 KBS2에서 2009년 10월 23일 첫 방송된 예능 프로그램으로, 걸그룹 멤버 7인(''G7'')이 농촌 마을에 머물며 자급자족 생활을 하는 콘셉트였다. 소녀시대 유리와 써니, 카라 구하라, 브라운아이드걸스 나르샤, 포미닛 현아, 티아라 효민, 시크릿 한선화가 초기 멤버였다. 제작진은 여러 장소를 옮겨 다니는 기존 예능과 달리 한곳에 정착하는 ''정착형 예능''이라고 소개했다. 이후 시즌1은 2010년 12월까지 이어졌고 시즌2는 어촌으로 무대를 옮겼다. 2009년 아이돌 예능을 떠올릴 때 자주 언급된다.',
  origin = '2009년 10월 23일 KBS2에서 시작했으며 시즌1 무대는 강원도 홍천군 유치리로 알려져 있다. 2010년 3월 세계일보 인터뷰에서 김호상 PD가 콘셉트를 설명했다. 방송 당시 시청률이 폭발적이지는 않았다고 PD가 말한 점이 확인된다.',
  usage_note = '2009~2010년 아이돌 예능과 걸그룹 전성기를 회상할 때 ''청춘불패 시절''처럼 언급한다. 아이돌이 농사나 시골 생활을 하는 예능 콘셉트를 설명하는 기준점으로도 쓰인다.',
  caution = '실존 아이돌의 방송 장면을 클립이나 짤로 재가공할 때는 방송사 저작권과 초상 문제가 있고, 당시의 외모 평가나 성희롱성 자막을 지금 기준으로 재소비하는 것은 부적절하다. 시즌별로 멤버 구성이 달라 사실 관계를 섞어 말하지 않도록 주의해야 한다.',
  usage_examples = '[{"situation":"예능 추억 이야기","text":"청춘불패 때 그 멤버들 지금 보니까 다들 엄청 컸네"},{"situation":"친구와 카톡","text":"요즘 아이돌 시골 예능 보면 청춘불패 생각나더라 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'kypyp4vj'
  and slug = '청춘불패'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

