-- 오버워치 씨나인(C9) (mar9fhpz / 오버워치-씨나인(C9))
update public.memes set
  description = 'C9은 본래 미국 e스포츠 팀 클라우드9(Cloud9)의 약칭이지만, 오버워치에서는 교전에서 이겨 놓고도 거점이나 화물에 붙지 않아 상대에게 승리를 내주는 실수를 가리키는 말로 쓰인다. 킬을 쫓거나 몸을 사리느라 목표를 비우는 플레이가 전형적인 사례다. 코타쿠는 2017년 2월 APEX 대회에서 클라우드9이 Afreeca Blue를 상대로 같은 이유로 세트를 내준 일에서 용어가 나왔다고 설명하고, PC 게이머도 같은 실수를 하는 프로 선수들을 두고 클라우드9에서 따온 밈이라고 소개한다. 이후 일반 게임에서도 널리 쓰이는 은어가 되었다.',
  origin = '2017년 2월 APEX 대회에서 클라우드9이 Afreeca Blue전에서 목표 지점을 비워 둔 채 진 경기에서 비롯된 것으로 코타쿠가 전하며, PC 게이머는 2017년 9월 기사에서 이를 널리 알려진 밈으로 다룬다. 한국 커뮤니티에서의 확산 경위는 열람한 출처로 확인하지 못했다.',
  usage_note = '다 이긴 한타에서 거점에 붙지 않아 역전당했을 때 ''C9 났다''처럼 쓴다. 게임 외에도 이긴 상황에서 마무리를 놓치고 허무하게 지는 일에 빗대어 쓰기도 한다.',
  caution = '특정 선수나 팀을 조롱하는 말로 번지기 쉬우며, 실제로 클라우드9 소속이었던 선수가 이 밈 때문에 곤란함을 토로한 사례도 있다. 게임 초보에게 쓰면 비난으로 들릴 수 있어 팀 채팅에서는 감정 싸움으로 이어지지 않게 주의해야 한다.',
  usage_examples = '[{"situation":"오버워치 보이스 채팅","text":"한타 이겼는데 왜 아무도 안 밟아? 이거 완전 C9잖아 ㅋㅋ"},{"situation":"친구와 카톡","text":"어제 3:0으로 이기다가 역전당했어. 마지막에 C9 제대로 났다"}]'::jsonb,
  origin_year = 2017,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'mar9fhpz'
  and slug = '오버워치-씨나인(C9)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

