-- 펭수 "펭하" (rgazmqqx / 펭수-"펭하")
update public.memes set
  description = '펭하는 EBS 캐릭터 펭수가 쓰는 인사말로, 위키백과는 펭수가 펭빠, 펭러뷰와 함께 대중화한 유행어로 소개한다. 펭수는 EBS 연습생이라는 설정의 거대 펭귄 캐릭터로, 유튜브 채널 자이언트 펭TV를 통해 알려졌다. 2019년 EBS 아이돌 육상대회(이육대) 영상이 화제가 되면서 어린이뿐 아니라 어른 시청자층까지 팬이 늘었다. 이 인기에 힘입어 펭하는 가볍게 인사를 건네는 말로 온라인에서 널리 쓰였다. 위키백과는 펭수가 성인 팬층, 이른바 키덜트에게도 인기를 얻었다고 설명한다.',
  origin = '펭수는 EBS 제작진이 만든 캐릭터로 2019년 3월 EBS 프로그램에 처음 등장했고, 같은 해 9월 자이언트 펭TV의 이육대 영상이 화제가 되었다. 펭하라는 말 자체의 첫 사용 시점은 열람한 출처로 확인하지 못했다.',
  usage_note = '온라인 댓글이나 메신저에서 장난스럽고 친근하게 ''펭하''로 인사를 건넬 때 쓴다. 펭수 팬덤 ''펭클럽'' 사이에서는 특히 자주 쓰이며, 동료나 친구와의 가벼운 대화에서 분위기를 풀어 주는 역할을 한다.',
  caution = '2019년 유행 당시의 표현이라 지금은 다소 옛 느낌을 줄 수 있고, 펭수는 EBS가 관리하는 캐릭터이므로 이미지나 영상을 상업적으로 쓰면 저작권 문제가 생길 수 있다. 캐릭터 설정에 관한 논란을 실제 인물 비하로 연결하지 않는 것이 좋다.',
  usage_examples = '[{"situation":"단톡방 아침 인사","text":"다들 펭하~ 오늘도 힘내봅시다"},{"situation":"친구와 카톡","text":"펭하! 나 지금 퇴근했다, 오늘 진짜 수고했어"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'rgazmqqx'
  and slug = '펭수-"펭하"'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

