-- 카트라이더 열풍 (skmxpejn / 카트라이더-열풍)
update public.memes set
  description = '2004년 넥슨이 선보인 온라인 레이싱 게임 크레이지레이싱 카트라이더가 짧은 기간에 전 연령층으로 퍼져 사회적 현상처럼 번진 일을 가리킨다. 조작이 쉽고 승부 부담이 적으며 캐릭터가 귀여워 PC방을 넘어 일상 대화의 소재가 되었고, 후일 그 시절의 국민 게임을 떠올릴 때 대표 사례로 언급된다. 단일 게임의 회원 수가 기존 대형 온라인 게임을 앞섰다는 점에서 업계에서도 이례적인 일로 받아들여졌고, 이후 캐주얼 게임 시장이 커지는 흐름의 출발점으로 이야기되기도 한다. 이 표현은 특정 장면이 아니라 시대의 분위기를 한마디로 묶는 말에 가깝다.',
  origin = '2004년 6월 오픈 베타를 시작해 같은 해 8월 회원 100만 명, 10월 동시접속자 10만 명을 넘겼고, 2005년 초에는 회원 1000만 명 돌파가 보도되었다. 한국 서비스는 2023년 3월 종료되었다.',
  usage_note = '2000년대 중반에 한 게임이 세대를 가리지 않고 유행했던 분위기를 설명하거나, 친구들과 추억의 게임 이야기를 나눌 때 비유로 쓴다. 최근 유행하는 게임을 두고 카트라이더급이라고 견주기도 한다.',
  caution = '유행의 정점 수치는 매체와 집계 기준(누적 회원, 동시접속자)에 따라 다르므로 단정적으로 인용하지 않는 편이 좋다. 게임 서비스 형태가 바뀌어 현재 상황과 혼동하지 않도록 시점을 밝혀야 한다.',
  usage_examples = '[{"situation":"어린 시절 게임을 추억할 때","text":"초딩 때 카트라이더 열풍이라 방과 후에 다 같이 PC방 갔던 기억 난다."},{"situation":"새 게임이 인기를 끌 때","text":"요즘 이 게임 인기 장난 아닌데, 거의 카트라이더 열풍급 아니냐."}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'skmxpejn'
  and slug = '카트라이더-열풍'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

