-- 어몽어스 스트리밍 붐 (dxknx6eh / 어몽어스-스트리밍-붐)
update public.memes set
  description = '2018년에 나온 협동·추리 게임 어몽어스가 2020년 스트리머들의 합동 방송을 계기로 갑자기 대중적 인기를 얻은 현상이다. 우주선 승무원 사이에 숨은 임포스터를 찾는 마피아형 규칙 덕분에 여럿이 모여 대화하며 노는 방송 콘텐츠로 잘 맞았고, 트위치와 유튜브에서 관련 영상이 크게 늘었다. 서로를 의심하고 설득하는 과정에서 시청자가 웃을 만한 순간이 자주 생겨 여러 스트리머가 같은 판에서 맞붙는 합동 방송이 특히 인기를 끌었다. 낮은 사양과 간단한 규칙도 진입 장벽을 낮춘 요인으로 꼽힌다.',
  origin = '출시는 2018년이었으나 2020년 6월경 한국 스트리머들의 방송을 시작으로 트위치 시청자가 늘었고, 2020년 9월 유튜브에서 관련 영상 조회수가 40억 회를 넘었다고 보도되었다. 국내 붐의 세부 경과는 확인하지 못했다.',
  usage_note = '코로나 시기 온라인 방송 문화를 이야기하거나, 스트리머들이 모여 즐기던 마피아형 게임 유행을 언급할 때 쓴다. 오래된 게임이 뒤늦게 재조명된 사례를 설명하는 데도 인용된다.',
  caution = '코로나19로 외출이 줄었던 시기와 엮이므로 인과를 단정하기 어렵다. 방송 클립을 쓸 때는 원 제작자의 저작권을 확인해야 하며, 특정 스트리머 한 명이 붐을 만들었다고 단순화하지 않아야 한다.',
  usage_examples = '[{"situation":"2020년을 회고할 때","text":"어몽어스 스트리밍 붐 때 합방 보느라 밤새던 거 기억나냐."},{"situation":"게임 재유행을 이야기할 때","text":"몇 년 된 게임이 갑자기 뜨는 거 어몽어스 붐 때랑 비슷하네."}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'dxknx6eh'
  and slug = '어몽어스-스트리밍-붐'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

