-- 황희찬 결승골 세리머니 (cnsr69mt / 황희찬-결승골-세리머니)
update public.memes set
  description = '2022년 카타르 월드컵 조별리그 H조 3차전 포르투갈전에서 황희찬이 후반 추가 시간에 역전 결승골을 넣은 뒤 상의를 벗고 환호하며 달린 장면을 가리킨다. 이 골로 한국은 2대1로 이기고 12년 만에 16강에 올라 극적인 순간의 상징처럼 회자되며 짤과 영상으로 반복 소비되었다. 경기 전까지 16강 진출이 불투명했던 만큼 감정이 폭발한 장면이라는 점이 강조되며, 이후 비슷한 극적인 득점이나 승부처를 말할 때 이 장면이 비유로 따라붙곤 한다. 득점 직후 곧바로 이어진 환호와 달리기까지 하나의 장면으로 묶여 소비된다.',
  origin = '2022년 12월 2일(한국시간 3일) 카타르 알라이얀에서 열린 경기에서 손흥민의 패스를 받은 황희찬이 득점했다. 신문 사진 기사에도 득점 후 상의를 벗고 내달리는 모습이 실렸다. 별명 등 파생 표현의 유래는 확인하지 못했다.',
  usage_note = '극적인 역전승이나 기쁨이 폭발하는 순간을 표현할 때 이 장면을 인용한다. 월드컵 16강 진출의 명장면으로 꼽을 때나 축구 팬 사이의 추억담에서 쓰인다.',
  caution = '실존 선수의 신체와 외모를 희화화하는 농담으로 번지지 않도록 주의해야 한다. 경기 영상 클립은 방송사 저작권이 있어 그대로 재업로드하기 어렵고, 파생 별명은 출처가 확인되지 않아 사실처럼 단정하면 안 된다.',
  usage_examples = '[{"situation":"역전승 직후","text":"이 마지막에 터지는 거 진짜 황희찬 포르투갈전 세리머니 각이다."},{"situation":"월드컵을 회상할 때","text":"2022 포르투갈전 황희찬 골 넣고 옷 벗고 뛰던 거 아직도 소름이다."}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'cnsr69mt'
  and slug = '황희찬-결승골-세리머니'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

