-- 혼밥 혼술 (d22wzeuj / 혼밥-혼술)
update public.memes set
  description = '혼밥은 혼자 먹는 밥, 혼술은 혼자 마시는 술을 줄여 부르는 말로, 혼자 하는 활동에 ''혼''을 붙이는 조어 방식의 대표 사례다. 1인 가구가 크게 늘던 2010년대 중반 언론 기사에서 혼영(혼자 보는 영화), 혼행(혼자 가는 여행), 혼쇼(혼자 하는 쇼핑) 같은 파생어와 함께 자주 등장하며 일상어로 자리 잡았다. 외로움의 표현이라기보다 혼자만의 시간을 즐기는 생활 방식을 가리키는 말로 쓰이는 경우가 많다. 2016년 기사들은 1인 가구가 500만 가구를 넘어선 통계와 함께 이 표현을 소개했고, 편의점 간편식이나 1인용 메뉴 같은 소비 흐름과도 연결해 다뤘다.',
  origin = '2016년 기사들이 1인 가구 증가와 함께 혼밥·혼술을 신조어로 소개했다. 특허청 자료에서는 ''혼밥'' 상표가 2015년, ''혼술''은 2016년에 처음 출원된 것으로 보도됐다. 처음 쓴 사람은 확인하지 못했다.',
  usage_note = '식당이나 술집, 영화관 등에서 혼자 이용하는 상황을 설명할 때 ''오늘은 혼밥'', ''주말엔 혼술''처럼 짧게 쓴다. 혼자 이용하기 편한 가게를 소개하는 광고와 후기에도 널리 쓰이며, 일상 대화에서는 이제 신조어라기보다 평범한 표현에 가깝다.',
  caution = '혼자 지내는 사람을 쓸쓸하다고 단정하는 맥락에서 쓰면 무례하게 들릴 수 있다. 혼술은 음주를 가볍게 미화하거나 과음을 부추기는 이미지로 이어질 수 있어 건강 관련 글에서는 표현에 주의해야 한다. 말의 정착 시기는 기사마다 조금씩 다르다.',
  usage_examples = '[{"situation":"점심 약속이 취소됐을 때","text":"오늘 점심은 혼밥 각이다, 새로 생긴 국밥집 가봐야지"},{"situation":"주말 계획 이야기","text":"금요일 저녁엔 영화 틀어놓고 혼술하면서 쉴 거야"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'd22wzeuj'
  and slug = '혼밥-혼술'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

