-- 날개 잃은 천사 (mwxwhfpq / 날개-잃은-천사)
update public.memes set
  description = '날개 잃은 천사는 혼성 그룹 룰라의 2집 타이틀곡으로, 1995년 3월 발매 직후 큰 인기를 얻어 가요계 댄스 열풍을 대표하는 곡이 됐다. 당시 신문은 김건모의 앨범에 이어 룰라 2집이 100만 장을 넘겼다고 전하며 댄스 음악의 쏠림을 우려하기도 했다. 레게풍 댄스 팝의 흐름 속에서 중독성 있는 멜로디와 군무가 인기를 끌었고, 지금도 90년대 가요를 회고할 때 빠지지 않고 언급된다. 음반은 레게풍 댄스 팝 열풍을 타고 대중의 큰 사랑을 받았다는 설명이 위키백과에 실려 있으며, 영문 위키는 1995년 서울가요대상 대상 수상 기록도 싣고 있다.',
  origin = '룰라 2집 《날개잃은 천사》는 1995년 3월 28일 발매됐고, 1995년 5월 8일자 서울신문은 이 앨범이 100만 장을 넘었다고 보도했다. 곡을 만든 구체적 제작 일화는 확인한 자료에서 찾지 못했다.',
  usage_note = '90년대 댄스가요나 복고 무대를 이야기할 때, 또는 군무가 돋보이는 장면에 ''날개 잃은 천사 느낌''이라고 빗대어 쓴다. 노래방, 복고 예능, 추억의 가요 모음 영상 댓글에서 흔히 보인다.',
  caution = '룰라는 이후 멤버 관련 논란이 여러 차례 알려진 그룹이라 출연자 개인을 언급할 때는 사실관계에 주의해야 한다. 당시 방송 영상이나 음원을 쓸 때는 저작권이 있다는 점을 고려해야 하고, 특정 시대의 유행을 과장해 일반화하지 않는 편이 좋다.',
  usage_examples = '[{"situation":"복고 영상 댓글","text":"이 군무 완전 날개 잃은 천사 때 룰라 느낌이다"},{"situation":"친구와 노래방에서","text":"90년대 댄스곡 하면 날개 잃은 천사부터 떠오르지"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'mwxwhfpq'
  and slug = '날개-잃은-천사'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

