-- 삼사(3! 4!) 구호 (tet9nfv7 / 삼사(3!-4!)-구호)
update public.memes set
  description = '삼사 구호는 룰라가 1996년 발표한 노래 ''3! 4!''의 도입부에서 외치는 ''3! 4!'' 소리를 가리킨다. 3전 4기라는 뜻을 담아 표절 논란으로 활동이 흔들렸던 룰라의 재기를 응원하는 의미로 만들어졌고, 가사도 지난 시련을 딛고 다시 시작하자는 내용이다. 곡은 발매 후 큰 인기를 얻어 1996년 여름을 대표하는 히트곡이 됐으며, 그 외침이 무언가를 시작하거나 힘을 모으는 신호처럼 가볍게 인용되곤 한다. 도입부 외침이 메트로놈 박자에 딱 맞춘 것이 아니라 감으로 부른 것이라 박자를 정확히 맞추기 어렵다는 점도 소개된다.',
  origin = '룰라 4집 《올 시스템 고》가 1996년 6월 15일 발매됐고 ''3! 4!''가 타이틀곡이다. 곡은 이현도가 만들었으며, 도입부 외침은 채리나가 감으로 불렀다고 보도됐다. 외침이 국민 구호로 퍼졌다는 점은 직접 확인하지 못했다.',
  usage_note = '회식이나 모임에서 건배나 시작 신호처럼 ''쓰리 포'' 하고 외치거나, 90년대 노래를 패러디하는 예능과 영상에서 가볍게 쓴다. 상황을 끝내고 다시 시작하자는 분위기를 만들 때 농담처럼 인용하기도 한다.',
  caution = '저장된 ''1995년'' 연도는 틀렸고 곡은 1996년 작품이다. 룰라 멤버 중 범죄로 처벌받은 인물이 있어 멤버 개인을 언급하면 불쾌감을 줄 수 있다. 원곡 영상은 저작권이 있으므로 그대로 올릴 때는 유의해야 한다.',
  usage_examples = '[{"situation":"모임 시작 전","text":"자, 다들 잔 들어봐요. 룰라 스타일로 쓰리, 포 하고 시작합시다"},{"situation":"새 프로젝트 시작 때 단톡방","text":"3전 4기 정신으로 다시 가보자 쓰리 포!"}]'::jsonb,
  origin_year = 1996,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'tet9nfv7'
  and slug = '삼사(3!-4!)-구호'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

