-- 그리운 어머니 (uvdujpcy / 그리운-어머니)
update public.memes set
  description = '그리운 어머니는 MBC 군 위문 프로그램 ''우정의 무대''의 하이라이트로 꼽힌 코너로, 군복무 중인 아들과 어머니가 상봉하는 모습을 보여 주던 장면을 가리킨다. 진행자 이상용이 두 사람의 만남을 따뜻하게 지켜봤고, 눈물을 흘리는 모습이 시청자에게 깊은 인상을 남겼다. 같은 이름의 곡이 프로그램의 주제가로 쓰였다는 기록도 있어, 지금도 눈물을 자아내는 감동 장면을 가리킬 때 이 이름이 인용된다. 군 위문 프로그램이라는 성격상 장병과 가족의 만남이 중심이 되었고, 진행자의 ''고향 앞으로'' 같은 멘트도 함께 기억된다.',
  origin = '''우정의 무대''는 1989년 시작했고 이상용이 1989년 4월부터 1996년 10월까지 진행했다. 위키백과는 ''그리운 어머니(작은별 가족)''를 주제가로 소개한다. 코너의 시작 연도와 구체적인 구성은 확인하지 못했다.',
  usage_note = '가족 상봉이나 부모와의 이별 장면처럼 눈물이 나는 상황을 말할 때 ''완전 우정의 무대 그리운 어머니 장면''처럼 비유한다. 군 복무와 어머니 이야기가 나올 때 90년대 추억으로도 언급된다.',
  caution = '진행자 이상용은 2025년 별세한 것으로 보도되어 고인을 다룰 때 예의를 지켜야 한다. 실제 군인 가족의 사연을 소재로 한 장면이라 웃음거리로 삼는 패러디는 불쾌감을 줄 수 있다. 방송 영상은 MBC의 저작물이다.',
  usage_examples = '[{"situation":"감동적인 영상 댓글","text":"이거 보니까 우정의 무대 그리운 어머니 코너 생각나서 눈물 난다"},{"situation":"군대 얘기 중 가족 이야기","text":"훈련소 퇴소날 엄마 보니까 진짜 그리운 어머니 찍는 줄 알았어"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'uvdujpcy'
  and slug = '그리운-어머니'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

