-- 한사랑산악회 (3c4pa4bt / 한사랑산악회)
update public.memes set
  description = '한사랑산악회는 유튜브 채널 피식대학이 2021년에 선보인 콩트 시리즈로, 중년 등산 모임의 모습을 현실적으로 재현해 큰 인기를 얻었다. KBS, SBS 공채 출신 개그맨 김민수, 이창호, 이용주, 정재형이 가정이나 사회에서 한 번쯤 마주쳤을 법한 중년 남성 캐릭터를 연기한다. 이창호가 맡은 이택조 부회장처럼 허리춤까지 올린 바지, 어색한 손가락 하트 같은 디테일이 웃음을 주고, 노래방에서 부른 ''피치스'' 개사 영상이 화제가 되며 유행어까지 낳았다.',
  origin = '2021년 6월~7월 기사들이 피식대학의 콩트 ''한사랑산악회''를 인기 코너로 소개했다. 출연진은 김민수, 이창호, 이용주, 정재형이며, 스눕독이 영상을 공유했다는 점도 보도됐다. 첫 공개 날짜는 확인하지 못했다.',
  usage_note = '등산복 입은 중년 아저씨 감성이나 어색한 사교 장면을 말할 때, 또는 영상 속 대사와 ''열쩡'' 같은 말을 따라 하며 가볍게 쓴다. 직장인 커뮤니티와 SNS에서 아저씨 개그의 대표 예로 자주 언급된다.',
  caution = '실제 중년 남성이나 등산 동호인을 비하하는 용도로 쓰면 의도와 다르게 세대 갈등을 부추길 수 있다. 콩트 속 캐릭터는 연기이므로 출연자 개인의 성격과 혼동하지 않아야 한다. 영상과 캡처를 무단 재편집해 올리면 저작권 문제가 생길 수 있다.',
  usage_examples = '[{"situation":"직장 동료와 대화","text":"부장님 바지 올려 입은 거 보니까 한사랑산악회 이택조 부회장 같다 ㅋㅋ"},{"situation":"SNS 영상 공유","text":"한사랑산악회 아저씨들 노래방 영상은 몇 번을 봐도 웃기다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '3c4pa4bt'
  and slug = '한사랑산악회'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

