-- 젠틀맨 (j27qcfsq / 젠틀맨)
update public.memes set
  description = '젠틀맨은 싸이가 2013년 4월 13일 유튜브로 공개한 노래로, 강남스타일 이후 내놓은 후속곡이다. 뮤직비디오에는 무한도전 멤버들과 가인이 출연했고, 뻔뻔하게 진상을 부리는 남성을 코믹하게 그리며 ''시건방춤''을 부각시켰다. 공개 31시간 만에 3000만 조회수를 넘겨 국내 가수 최단 기록을 세웠고, 앵그리버드나 텔레토비를 활용한 패러디도 쏟아졌다. 5월에는 유튜브 조회수 3억 건을 돌파해 역대 26위에 올랐다. 뮤직비디오는 코믹한 연출과 중독성 있는 춤으로 해외에서도 주목을 받았다는 보도가 이어졌다.',
  origin = '젠틀맨 뮤직비디오는 2013년 4월 13일 오후 유튜브 공식 채널에 올라왔다. 세계일보와 경향신문은 공개 직후의 조회수 기록과 패러디 영상을 보도했다. 시건방춤이 특정 곡의 안무를 재해석했다는 설명은 확인하지 못했다.',
  usage_note = '상대의 뻔뻔한 행동을 놀리거나, 시건방춤 포즈를 따라 하며 장난스럽게 분위기를 띄울 때 쓴다. 학교 장기자랑이나 행사에서 패러디 영상으로도 많이 소비됐으며, 지금은 2010년대 초반 K팝 열풍을 떠올리는 복고 소재다.',
  caution = '영상 속 인물은 과장된 진상 캐릭터이므로 실제 사람을 놀릴 때 그대로 적용하면 모욕으로 받아들여질 수 있다. 공개 직후 수치는 당시 집계라 현재와 다르다. 외국 패러디 중에는 특정 인물을 희화화한 것도 있어 무분별한 공유에 주의해야 한다.',
  usage_examples = '[{"situation":"친구가 새치기했을 때","text":"야, 방금 그 행동 완전 젠틀맨 뮤비 급 진상인데 ㅋㅋ"},{"situation":"장기자랑 준비하며","text":"우리 반은 젠틀맨 시건방춤으로 가자, 안무 쉬워서 바로 외울 수 있어"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'j27qcfsq'
  and slug = '젠틀맨'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

