-- 나야나(프로듀스101) (uskrnffh / 나야나(프로듀스101))
update public.memes set
  description = '나야 나는 Mnet 오디션 프로그램 프로듀스101 시즌2의 첫 주제곡으로, 연습생들이 단체로 부른 곡이다. 2017년 3월 곡 제목이 알려졌고, 방송 시작 직전에 무대 영상이 먼저 공개되어 화제가 됐다. 3회 방송에서는 이대휘가 이 곡의 센터로 선정됐다. 자신을 뽑아 달라고 어필하는 가사와 안무가 인상적이어서 방송 기간 내내 각종 예능의 패러디와 응원 문화로 이어졌고, 시즌 종료 후에도 2017년을 대표하는 곡으로 기억된다. 이 곡은 앞선 시즌의 ''픽미''처럼 인기를 끈 대표곡의 뒤를 잇는 곡으로 소개됐고, 3회 방송은 당시 프로그램 자체 최고 시청률을 경신했다는 보도도 있다.',
  origin = '2017년 3월 9일 위키트리가 엑스포츠뉴스를 인용해 곡 제목이 ''나야 나''라고 전했다. 작곡은 라이언 전으로 보도됐고, 4월 21일 방송 3회에서 센터 이대휘가 확정됐다. 안무 장면별 세부 정보는 확인하지 못했다.',
  usage_note = '자기를 알아봐 달라는 장난스러운 상황이나 오디션 같은 분위기를 만들 때 ''나야 나!'' 하고 손동작을 따라 하며 쓴다. 단체 채팅방에서 자기소개를 하거나 모임에서 지목당했을 때 가볍게 쓰기 좋다.',
  caution = '특정 연습생이나 출연자를 비하하는 합성 이미지로 쓰면 팬 간 갈등이나 명예훼손 문제가 될 수 있다. 방송 영상과 안무 클립은 CJ ENM 등 권리자의 저작물이므로 무단 업로드에 주의해야 하고, 2017년 시즌 유행이라 이후 세대에게는 맥락이 낯설 수 있다.',
  usage_examples = '[{"situation":"단톡방 자기소개","text":"새로 온 팀원 소개할게요. 이름은 김OO, 나야 나!"},{"situation":"조별 과제 발표자 정할 때","text":"발표 누가 할래? 나야 나 나야 나~ 내가 할게"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'uskrnffh'
  and slug = '나야나(프로듀스101)'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

