-- 회상 (7fpmdazd / 회상)
update public.memes set
  description = '회상은 댄스 그룹 터보가 1997년 발표한 3집 《Born Again》의 수록곡으로, 영문 제목은 December다. 감성적인 미디엄 템포 곡으로 알려져 터보의 대표적인 겨울 노래로 꼽힌다. 이 앨범은 회상, 굿바이 예스터데이, 금지된 장난 등이 인기를 얻어 100만 장 넘게 팔렸다고 보도됐다. 2015년 터보가 15년 만에 새 앨범을 낼 때도 회상 같은 감성의 곡이 언급될 만큼 오랫동안 회자됐다. 영문 위키는 이 곡이 차트 71위를 기록한 것으로 정리하고 있다.',
  origin = '터보 3집 《Born Again》은 1997년 마이키가 합류한 뒤 발매됐고 회상은 이 앨범의 곡이다. 영문 위키는 1997년 곡으로 정리했다. 김종국이 이 곡을 가장 아끼는 곡으로 꼽았다는 내용은 확인하지 못했다.',
  usage_note = '추운 날씨나 겨울 감성을 이야기할 때, 또는 90년대 가요를 추억하는 대화에서 ''회상 들으면 겨울이 생각난다''처럼 쓴다. 노래방 선곡이나 복고 플레이리스트에서도 자주 보인다.',
  caution = '저장 본문은 이 곡을 2집 수록곡이라고 했지만 자료상 3집이다. 김종국의 개인적 애정에 관한 주장은 근거가 없으므로 사실처럼 옮기면 안 된다. 음원과 뮤직비디오는 저작권이 있고, 일상어 ''회상''과 혼동되는 검색어이므로 곡 이름임을 밝혀 쓰는 편이 좋다.',
  usage_examples = '[{"situation":"겨울 노래 추천 대화","text":"눈 오는 날엔 터보 회상 틀어야지, 이건 겨울 필수곡이야"},{"situation":"노래방에서","text":"김종국 목소리 그대로 회상 한 번 불러볼게"}]'::jsonb,
