-- 아기상어 (3zm24ew8 / 아기상어)
update public.memes set
  description = '아기상어는 더핑크퐁컴퍼니가 만든 동요 ''상어 가족'' 영상을 가리키는 말로, 특히 아이들의 율동이 더해진 ''아기상어 체조(Baby Shark Dance)'' 영상이 전 세계적으로 유명하다. 2016년 6월 공개된 이 영상은 ''뚜루루뚜루'' 후렴구와 따라 하기 쉬운 안무로 인기를 끌었다. 2020년 11월 유튜브 조회수 1위에 올라 기네스북에 등재됐고, 2022년 1월에는 유튜브에서 처음으로 100억 뷰를 넘겼다. 한번 들으면 머릿속에서 맴도는 노래라는 뜻의 비유로도 쓰인다.',
  origin = '원곡 영상은 2015년 처음 공개됐고, 율동 버전인 ''핑크퐁 아기상어 체조''는 2016년 6월 공개됐다. 2022년 1월 13일 누적 조회수 100억 뷰를 넘었다고 제작사가 밝혔다. 원곡이 전래 동요에서 왔다는 설은 확인하지 못했다.',
  usage_note = '귀에 계속 맴도는 노래나 반복되는 상황을 말할 때 ''아기상어급 중독성''이라고 쓴다. 아이가 있는 부모 사이에서는 율동을 따라 하거나 육아 중 겪는 에피소드를 이야기할 때 자주 등장한다.',
  caution = '영상 속 캐릭터와 음원은 핑크퐁의 저작물이므로 상업적 편집에는 허락이 필요하다. 조회수는 집계 시점마다 달라 수치를 쓸 때 날짜를 밝히는 편이 좋다. 어린이 콘텐츠라 성인용 패러디로 변형하면 부적절하다고 받아들여질 수 있다.',
  usage_examples = '[{"situation":"귀에 맴도는 노래를 말할 때","text":"하루 종일 이 노래가 머릿속에서 안 떠나, 거의 아기상어급 중독성이야"},{"situation":"아이와 놀며","text":"우리 애는 아기상어 체조만 틀어주면 바로 따라 춰요 ㅋㅋ"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '3zm24ew8'
  and slug = '아기상어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

