-- 바비코어 (77ttczeh / 바비코어)
update public.memes set
  description = '바비코어는 인형 바비를 연상시키는 선명한 핑크 색감과 인형 같은 실루엣을 앞세운 패션 흐름을 가리키는 말이다. 머리부터 발끝까지 핫핑크로 맞추는 과감한 코디가 대표적이며, 일상에서는 핑크 아우터 하나만 더해 가볍게 즐기기도 한다. 2023년 7월 개봉한 영화 ''바비''를 앞두고 패션계 전반에서 큰 흐름이 되었고, 틱톡에서도 관련 해시태그가 크게 늘며 확산되었다. 보그 코리아는 바비의 핑크가 영화 개봉 때까지 이어질 흐름이라고 전했고, 하퍼스 바자 코리아는 마고 로비 사진 공개 뒤 한 패션 사이트의 핑크 검색량이 416% 늘었다고 소개했다.',
  origin = '국내외 매체는 영화 ''바비''의 제작 소식이 알려진 뒤 런웨이마다 바비 핑크가 등장했고 영화 개봉 전부터 시즌 핵심 트렌드가 되었다고 전한다. 이 말이 언제 처음 쓰였는지는 열어 본 자료에서 확인되지 않았다.',
  usage_note = '핑크 위주로 과감하게 차려입은 코디를 설명하거나 ''오늘 바비코어 룩이야''처럼 가볍게 스타일을 소개할 때 쓴다. 영화 ''바비'' 이야기나 인형 같은 분위기의 사진, 쇼핑 후기 등에 함께 붙이면 의미가 잘 전달된다.',
  caution = '영화 개봉에 맞춘 한시적 유행어라 시간이 지나면 다소 지난 표현으로 들릴 수 있다. 모든 핑크 옷을 바비코어라 부르면 과장이 되며, 특정 연예인이나 일반인의 옷차림을 인형 같다며 평가하는 투로 쓰면 외모 품평으로 느껴질 수 있다.',
  usage_examples = '[{"situation":"친구와 옷 구경 중","text":"이 핫핑크 재킷 완전 바비코어인데? 하나 사서 입고 싶다"},{"situation":"SNS 코디 사진 댓글","text":"핑크 올블랙 믹스한 바비코어 룩 너무 예뻐요"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '77ttczeh'
  and slug = '바비코어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

