-- 쿨 '애상' (7b4wppp7 / 쿨-애상)
update public.memes set
  description = '''애상''은 혼성 그룹 쿨이 1998년 4월 발매한 4집 앨범의 타이틀곡이다. 연애 관계 속 애매한 감정을 가볍고 밝은 멜로디로 풀어낸 댄스곡으로, 외환위기로 분위기가 가라앉은 시기에도 큰 사랑을 받았다. 당시 음반 판매량은 약 80만 장으로 전해지며 가요 프로그램에서 여러 차례 1위를 했다. 지금도 90년대 말 여름 댄스가요와 혼성 그룹을 이야기할 때 대표 곡으로 자주 언급된다. 엑스포츠뉴스는 이 곡이 가요 프로그램 1위를 모두 9회 차지하며 전성기를 이끌었다고 전한다.',
  origin = '1998년 4월 쿨 4집 ''애상''의 동명 타이틀곡이다. 1998년 한 해 50만 장 이상 팔린 음반 목록에 포함되었다는 기록이 있다. 구체적인 수상 내역은 열어 본 자료에서 확인하지 못했다.',
  usage_note = '90년대 가요나 혼성 그룹, 여름 노래 이야기에서 추억 소환용으로 쓴다. 노래방 선곡이나 복고 플레이리스트, 세대 공감 댓글에서 곡 제목만 말해도 통하는 편이다.',
  caution = '영상이나 음원 클립을 올릴 때는 원 저작권자의 권리를 확인해야 한다. 기존 설명에 있던 골든디스크, KBS 가요대상 수상 등은 열어 본 자료로 확인하지 못해 단정하지 않는 편이 안전하다. 멤버 개인에 대한 소식과 곡 이야기를 섞지 않도록 한다.',
  usage_examples = '[{"situation":"복고 플레이리스트 공유","text":"여름엔 역시 쿨 ''애상''이지, 이거 들으면 98년으로 돌아간 기분"},{"situation":"노래방에서","text":"혼성 그룹 노래 중엔 ''애상'' 이길 곡이 없다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '7b4wppp7'
  and slug = '쿨-애상'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

