-- 스시 구다사이 (9evd86p2 / 스시-구다사이)
update public.memes set
  description = '''구다사이''는 일본어로 ''주세요''를 뜻하는 말로, 미국의 틱톡 크리에이터 데빈 할발이 일본 여행 영상에서 이 단어를 반복해 ''구다사이 퀸''이라는 별명을 얻으면서 퍼졌다. 한국에서는 2024년 3~4월 그가 방한하자 ''스시 구다사이''를 함께 외치는 영상과 팬 모임이 SNS에서 화제가 되었다. 짧고 중독성 있는 말투를 따라 하는 밈으로, 음식을 주문하거나 무언가를 달라고 장난칠 때 쓰인다. 영상은 7개월 만에 1,400만 회 넘게 재생된 것으로 소개된다.',
  origin = 'Know Your Meme에 따르면 2024년 1월 27일 데빈 할발이 ''내가 아는 유일한 일본어''라는 설명과 함께 올린 영상이 시작이다. ''스시'' 부분이 누구에게서 왔는지는 열어 본 자료에서 확인하지 못했다.',
  usage_note = '음식을 주문하거나 친구에게 무언가를 졸라 달라고 할 때 ''○○ 구다사이''처럼 뒤에 단어를 바꿔 붙여 쓴다. 숏폼 영상 자막이나 댓글에서 유행어로 가볍게 인용하는 것이 일반적이다.',
  caution = '특정 크리에이터의 말투를 따라 하는 밈이라 상대 외모나 정체성을 조롱하는 방향으로 쓰지 않아야 한다. 일본어 표현이므로 일본 현지 가게에서 장난으로 외치면 무례하게 보일 수 있다. 기존 설명의 ''특유의 억양'' 부분은 근거가 없어 뺐다.',
  usage_examples = '[{"situation":"초밥집에서 주문하며","text":"여기 연어초밥이요, 스시 구다사이~"},{"situation":"친구에게 장난으로","text":"점심 쏴줘, 치킨 구다사이"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '9evd86p2'
  and slug = '스시-구다사이'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

