-- 대화가 필요해 "밥먹자" (abp29ywg / 대화가-필요해-"밥먹자")
update public.memes set
  description = '''대화가 필요해''는 KBS 개그콘서트의 인기 코너로, 김대희가 아버지, 신봉선이 어머니, 장동민이 아들로 나와 소통이 안 되는 가족을 그렸다. 이 코너에서 아버지가 던지는 ''밥묵자~'' 같은 말이 유행어가 되었고, 경제력이 없어 큰소리만 치는 아버지와 무식한 어머니, 공부 못하는 아들이라는 설정이 웃음을 만들었다. 코너는 2006년 11월부터 2008년 11월까지 약 2년간 100회 넘게 방송되었다. 김대희 본인도 20년 개그콘서트 활동 중 가장 기억에 남는 코너로 이 코너를 꼽는다고 인터뷰에서 밝혔다.',
  origin = '2006년 11월부터 2008년 11월까지 KBS 개그콘서트에서 방송된 코너로, 김대희·신봉선·장동민이 출연했다. 유행어는 ''밥먹자''가 아니라 사투리 표현인 ''밥묵자''로 소개된다.',
  usage_note = '가족이 대화는 안 하고 밥만 먹자고 할 때, 어색한 분위기를 풀고 싶을 때 장난스럽게 쓴다. 지금도 김대희의 유튜브 채널 ''꼰대희''의 대표 콘텐츠명으로 이어져 친숙하게 쓰인다.',
  caution = '저장된 제목은 ''밥먹자''이지만 원래 유행어는 ''밥묵자''로 보도되므로 인용할 때 표기에 유의한다. 방송 클립을 재업로드하면 저작권 문제가 생길 수 있고, 가부장적인 아버지를 희화화한 코미디여서 가족 갈등을 가볍게 넘기는 용도로 쓰면 오해를 살 수 있다.',
  usage_examples = '[{"situation":"가족 단톡방에서","text":"엄마, 오늘 저녁 뭐야? 아빠는 또 ''밥묵자'' 하겠네"},{"situation":"가족과 어색할 때","text":"대화가 필요해라더니 결국 밥묵자로 끝나네"}]'::jsonb,
