-- 베이비복스 - Get Up (ehwqcvex / 베이비복스---Get-Up)
update public.memes set
  description = '''Get Up''은 걸그룹 베이비복스가 1999년 3집 《Come Come Come Baby》에서 발표한 타이틀곡이다. 앞선 청순한 이미지에서 벗어나 성숙하고 요염한 분위기로 변신한 곡으로, 박진영이 작사했고 같은 해 8월 KBS 뮤직뱅크에서 그룹의 첫 음악방송 1위를 안겼다. 이 앨범은 걸그룹이 성숙하고 대담한 콘셉트를 시도하는 길을 연 작품으로 평가되며, 이후 여성 그룹 콘셉트 이야기에서 자주 언급된다. 주간경향도 1999년 세 번째 앨범에서 성숙함으로 콘셉트를 바꿨다고 설명한다.',
  origin = '1999년 6월 30일 공개된 3집 타이틀곡이다. 멤버 윤은혜가 합류한 뒤 같은 해 7월 컴백했다. 기존 소개의 ''2001년''은 오류로 보이며 ''국내 첫 섹시 콘셉트''라는 표현은 근거를 찾지 못했다.',
  usage_note = '2000년대 초 걸그룹 콘셉트의 변화나 베이비복스 활동기를 회상할 때 곡명을 언급한다. 복고 퍼포먼스 영상이나 노래방 선곡을 이야기할 때도 자주 쓰인다.',
  caution = '''국내 첫 섹시 콘셉트'' 같은 최초 표현은 확인되지 않은 평가이므로 단정하지 않는다. 의상이나 몸매를 중심으로 평가하는 댓글로 흐르지 않도록 하고, 무대 영상 사용 시 방송사와 소속사의 저작권을 확인해야 한다.',
  usage_examples = '[{"situation":"추억의 걸그룹 이야기","text":"베이비복스 ''Get Up'' 그때 무대 진짜 파격이었지"},{"situation":"노래방에서","text":"''Get Up''은 안무까지 외워야 완성이다"}]'::jsonb,
  origin_year = 1999,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'ehwqcvex'
  and slug = '베이비복스---Get-Up'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

