-- 고무짜기 (epzwegpc / 고무짜기)
update public.memes set
  description = '''고무짜기''는 고무나무에서 채취한 라텍스 덩어리를 손으로 쥐어짜 물기를 빼는 장면을 담은 짧은 영상을 말한다. 2025년 하반기 유튜브와 인스타그램 릴스, 틱톡에서 한국 이용자들 사이에 인기를 끌었고, 모짜렐라 치즈를 연상시키는 비주얼과 소리가 힐링 ASMR처럼 소비되었다. 댓글에서 ''완익'', ''덜익'' 같은 말로 질감을 품평하는 놀이 문화가 함께 퍼진 점이 특징이다. 한국경제와 인사이트는 반복되는 짧은 장면이 ''디지털 힐링''처럼 기능한다고 분석했다.',
  origin = '한국경제는 지난 6월 공개된 ''아시아 최대 고무 농장'' 영상이 190만 회를 넘겼고 2025년 10월 하순 한국에서 크게 확산되었다고 전한다. 처음 올린 계정은 확인하지 못했고, 한국 유행은 해외 영상을 한국 이용자가 소비하며 시작되었다고 소개된다.',
  usage_note = '짧은 영상에 ''오늘의 고무짜기''처럼 캡션을 달거나 완익, 덜익 같은 품평 용어를 댓글에 쓰며 즐긴다. 스트레스를 풀고 싶을 때 보는 힐링 영상이라는 의미로도 쓰인다.',
  caution = '해외 크리에이터의 영상을 가져와 재가공하면 저작권 문제가 생길 수 있다. 유행 주기가 짧아 곧 식을 수 있으며, 기존 설명의 ''고무를 늘리고 당기는'' 묘사와 달리 실제는 라텍스를 짜는 영상이므로 다른 ''쭉 늘리기'' 영상과 혼동하지 않아야 한다.',
  usage_examples = '[{"situation":"릴스를 보다가","text":"오늘도 고무짜기 보고 힐링 중, 이건 완익이다"},{"situation":"친구에게 영상 공유","text":"이 고무짜기 영상 소리 때문에 계속 보게 돼"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'epzwegpc'
  and slug = '고무짜기'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

