-- 핑크퐁 아기상어 (f5fmmfw5 / 핑크퐁-아기상어)
update public.memes set
  description = '''아기상어''는 더핑크퐁컴퍼니가 만든 동요 영상으로, 단순한 멜로디와 반복되는 ''뚜루루뚜루'' 후렴, 율동이 어린이뿐 아니라 전 세계로 퍼졌다. 노래는 2015년 처음 공개되었고, 율동을 더한 ''핑크퐁 아기상어 체조''가 2016년 6월 공개되어 세계적 인기를 끌었다. 이 영상은 2020년 11월 유튜브 최다 조회수 1위에 올랐고 2022년 1월에는 세계 최초로 100억 회를 넘겼다. 레이디경향은 이 영상이 2위였던 ''데스파시토'' 뮤직비디오보다 약 23억 뷰 높았다고 전했다.',
  origin = '더핑크퐁컴퍼니가 2015년 노래를 처음 공개했고, 2016년 6월 율동 버전 ''핑크퐁 아기상어 체조''가 나왔다. 이후 2022년 1월 유튜브 100억 뷰를 넘겼다고 보도되었다. 2016년 이전의 조회수 기록은 열어 본 자료에 없다.',
  usage_note = '아이가 있는 집에서 중독성 있는 멜로디를 두고 ''귀에서 안 떠난다''고 말할 때 쓴다. 아기상어 율동을 따라 하는 챌린지나 영상 밈에서 ''뚜루루뚜루''만으로도 통하는 유행어가 되었다.',
  caution = '어린이 콘텐츠이므로 성인용 풍자나 수정 영상에 아이 모습을 함께 쓰면 문제가 될 수 있다. 캐릭터와 음원은 업체가 권리를 가지므로 상업적 이용 시 허락이 필요하다. 반복되는 곡이라 ''세뇌송''으로 불리며 피로감을 호소하는 의견도 있다.',
  usage_examples = '[{"situation":"육아 중 하소연","text":"하루 종일 아기상어 틀어 달래서 내가 지금 뚜루루뚜루 하고 있어"},{"situation":"조카와 놀면서","text":"상어 가족 율동 하자, 엄마 상어 먼저!"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'f5fmmfw5'
  and slug = '핑크퐁-아기상어'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

