-- god - 길 (gahs5c53 / god---길)
update public.memes set
  description = '''길''은 그룹 god가 2001년 11월 발매한 정규 4집의 타이틀곡이다. 거친 랩 대신 부드럽고 사색적인 멜로디 랩을 도입해 멤버 전원이 보컬로 참여했고, 삶의 방향과 꿈에 대한 질문을 담은 가사로 많은 공감을 얻었다. 위키백과에 따르면 이 곡은 KBS, MBC, SBS 연말 시상식에서 모두 대상을 받았으며, 앨범은 골든디스크 어워즈 음반 대상을 수상했다. 지금도 god 대표곡이자 2000년대 초 가요를 상징하는 노래로 자주 거론되며, 한국갤럽 조사에서 한국인이 좋아하는 가요 100곡에 들었다.',
  origin = '2001년 11월 15일 발매된 g.o.d 4집 《Chapter 4》의 타이틀곡이며 박진영이 작사·작곡했다. 경향신문 2001년 보도에 따르면 멤버들이 만장일치로 이 곡을 타이틀로 정했다.',
  usage_note = '진로나 인생에 고민이 있을 때 ''나는 왜 이 길에 서 있나'' 같은 분위기를 빗대어 말할 때 쓴다. 졸업, 퇴사, 이직 같은 갈림길 이야기나 god 콘서트, 추억의 노래 선곡 이야기에서 자주 언급된다.',
  caution = '가사를 그대로 길게 인용하면 저작권 문제가 될 수 있고, 일부 가사만 가볍게 인용하는 정도가 적절하다. 멤버 개인의 근황이나 논란과 곡 이야기를 섞으면 오해가 생길 수 있으며, 시상식 수상 내역은 연도와 시상식을 정확히 확인해 쓰는 것이 좋다.',
  usage_examples = '[{"situation":"진로 고민 글에","text":"나는 왜 이 길에 서 있나 했던 god 노래가 요즘 딱 내 얘기다"},{"situation":"추억의 노래 선곡","text":"퇴근길엔 god ''길'' 틀어야 감성이 완성돼"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'gahs5c53'
  and slug = 'god---길'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

