-- 묻지도 따지지도 않고 (gv8wc8uv / 묻지도-따지지도-않고)
update public.memes set
  description = '''묻지도 따지지도 않고''는 라이나생명 광고에서 배우 이순재가 외친 카피로, 고령층을 겨냥한 보험을 간편하게 가입할 수 있다는 메시지를 담았다. 언론은 이 문구가 유행어가 되어 ''라이나생명은 이순재보험''이라는 인식을 만들었다고 평가한다. 이후 의미가 확장되어 ''이것저것 따지지 않고 무조건''이라는 뜻의 일상어처럼 쓰이게 되었다. 다만 이 문구가 처음 쓰인 연도와 광고의 세부 타깃 연령은 열어 본 자료로는 확인되지 않는다. 머니투데이는 라이나생명이 고령층 대상 갱신형 상품을 주로 판매한다고 설명한다.',
  origin = '라이나생명 광고에서 이순재가 말한 카피로 알려져 있다. 2009년에는 생명보험협회가 광고 심의 기준을 강화하면서 ''묻지도, 따지지도 않고'' 같은 표현을 금지 대상으로 보도되었다. 광고가 처음 나온 연도는 확인하지 못했다.',
  usage_note = '무언가를 이유 없이 받아들이거나 무조건 해 주겠다고 장난스럽게 말할 때 쓴다. ''묻지도 따지지도 않고 OK'' 같은 형태로 광고 말투를 흉내 내는 밈에 자주 보인다.',
  caution = '보험 가입에 심사가 전혀 없다는 의미로 오해하면 안 되고, 실제로는 상품마다 보장 범위와 가입 조건이 달라 협회가 이런 표현을 오인 가능성 때문에 제한한 사례가 있다. 배우의 목소리를 흉내 내는 영상은 초상·음성 이용에 주의해야 한다.',
  usage_examples = '[{"situation":"친구가 부탁할 때","text":"오늘 치킨은 묻지도 따지지도 않고 내가 쏜다"},{"situation":"가족 단톡방에서","text":"엄마가 필요하다는 건 묻지도 따지지도 않고 사드려야지"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'gv8wc8uv'
  and slug = '묻지도-따지지도-않고'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

