-- 돈쭐내다 (wxfgzd3n / 돈쭐내다)
update public.memes set
  description = '''돈쭐내다''는 ''돈''과 ''혼쭐내다''를 합친 신조어로, 좋은 일을 한 가게에 주문을 몰아 줘 매출로 보답한다는 뜻이다. 2021년 초 치킨 프랜차이즈 ''철인7호'' 홍대 점주가 형편이 어려운 형제에게 무료로 치킨을 내준 사연이 알려지자 누리꾼들이 ''돈쭐 내주자''며 주문에 나서면서 널리 퍼졌다. 전문가는 정의와 공정을 중시하는 MZ세대의 소비 성향과 연결 지어 설명했다. 사연이 알려진 뒤 주문이 몰려 해당 매장이 영업을 일시 중단하기도 했다고 보도되었다.',
  origin = '치킨 프랜차이즈 대표가 인스타그램으로 공개한 고등학생의 손편지(1월)에서 시작되었다. 편지에는 가진 돈이 5000원뿐이던 형제에게 점주가 무료로 치킨을 내준 일이 담겼다. 이 말이 그 전부터 쓰였는지는 확인하지 못했다.',
  usage_note = '선행을 베푼 가게나 사장님을 응원하며 주문을 늘리자고 할 때 쓴다. ''여기 돈쭐 내주자''처럼 SNS와 커뮤니티에서 소비로 응원한다는 의미를 담는다.',
  caution = '주문이 갑자기 몰려 매장이 영업을 중단하는 등 부담이 생긴 사례도 있어 기사에서는 점주가 후원 주문을 사양하고 기부를 이어 갔다고 전한다. 사연이 과장되거나 가게를 이용하려는 목적으로 쓰이지 않는지 확인이 필요하다.',
  usage_examples = '[{"situation":"미담 기사 댓글","text":"이런 사장님은 돈쭐 내줘야 해요, 저도 주문했어요"},{"situation":"친구에게 공유","text":"여기 사연 보니까 돈쭐 내주고 싶다, 이번 주말에 시켜 먹자"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = 'wxfgzd3n'
  and slug = '돈쭐내다'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

