-- 마라탕 신드롬 (2ud8yy8a / 마라탕-신드롬)
update public.memes set
  description = '마라탕은 얼얼한 향신료 맛이 특징인 중국식 탕 요리로, 2019년 한국에서 젊은 층을 중심으로 크게 유행해 ''마라 신드롬''이라 불렸다. 주간경향은 서울 대림동 식당들이 한국 입맛에 맞게 얼얼한 맛을 줄이고 매운맛을 더해 대중화의 길을 열었다고 전한다. 배달 앱에서는 마라 관련 음식점이 1년 만에 크게 늘었고, 식약처가 인기 마라탕 전문점 63곳을 점검해 37곳이 식품위생법을 위반한 사실이 알려지기도 했다. 주간경향은 2011년 무렵 대림동에도 마라탕집이 몇 곳 있었지만 대부분 중국 동북 지방 입맛에 맞춘 강한 맛이었다고 설명한다.',
  origin = '주간경향은 중국 동북 지방에서 국내로 들어온 마라 요리가 대림동 가게들의 현지화를 거쳐 대중화되었다고 전한다. 이 소개는 한 가게 주인의 증언을 바탕으로 하므로 전체 역사로 보기엔 한계가 있다.',
  usage_note = '유행 음식에 열광하는 현상을 설명하거나 ''혈중 마라 농도'' 같은 말로 마라 음식을 즐긴다는 뜻을 표현할 때 쓴다. 마라탕, 마라샹궈, 마라 간식이 늘어난 외식 트렌드를 이야기할 때도 쓰인다.',
  caution = '유행이 단기간에 급증해 위생 문제가 지적되었으므로 업소별 평가를 일반화하지 않아야 한다. 마라탕을 중국 문화와 정치 이슈로 연결해 비난하는 표현은 부적절하며, 기존 설명의 ''중국 유학생 대상 식당에서 시작''은 근거를 확인하지 못했다.',
  usage_examples = '[{"situation":"점심 메뉴를 정할 때","text":"오늘 혈중 마라 농도 떨어져서 마라탕 먹으러 가자"},{"situation":"맛집 후기에","text":"마세권에 이사 오니까 마라탕 신드롬이 실감 난다"}]'::jsonb,
  content_reviewed_at = '2026-11-21T09:00:00+09:00'::timestamptz,
  updated_at = now()
where short_id = '2ud8yy8a'
  and slug = '마라탕-신드롬'
  and moderation_status in ('approved'::public.moderation_status, 'limited'::public.moderation_status);

